import{_ as r,h as o,i as e,c as n,v as t,p as E,x as i,m as s,e as m,S as p}from"./chunks/framework.Dvtg8yj2.js";const g=JSON.parse('{"title":"REINFORCE / R3","description":"","frontmatter":{"title":"REINFORCE / R3","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reinforce-llm.md","filePath":"llm/reinforce-llm.md","lastUpdated":1788454257000}'),R={name:"llm/reinforce-llm.md"};function h(c,a,d,A,C,_){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="reinforce-r3" tabindex="-1">REINFORCE / R3 <a class="header-anchor" href="#reinforce-r3" aria-label="Permalink to &quot;REINFORCE / R3&quot;">​</a></h1><div class="epigraph"><p>用即时强化去乘对数策略梯度，不必学习值函数；减去一个不依赖当前动作的基线，可以降方差而不引入偏置。</p><footer>—— Williams, Simple Statistical Gradient-Following Algorithms for Connectionist Reinforcement Learning, Machine Learning 1992</footer></div><p>语言模型的强化学习一度被写成「必须上 PPO、必须训一个同规模 Critic」。Williams 在 1992 年给出的 REINFORCE 更朴素：从当前策略采样一整条轨迹，用这条轨迹的回报去乘每个动作的对数概率梯度。没有时序差分，没有 GAE，也没有第二套网络。DeepSeek-R1 一类工作把可验证奖励和<a href="/llm/critic-free-advantage">不依赖 Critic 的优势</a>重新推到前台之后，这条 1992 年的估计器又成了默认内核。本篇把 REINFORCE 写成语言模型上的蒙特卡洛策略梯度；标题里的 R3 指工程上常绑在一起的三件套——<strong>回报（Return）、REINFORCE 梯度、与参考策略的正则</strong>——不是另一篇需要虚构编号的论文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把一次生成看成马尔可夫决策过程：状态是提示加已写出的前缀，动作是下一个 token，策略是因果语言模型 \\(\\pi_\\theta(y_t\\mid x,y_{&lt;t})\\)。奖励几乎总在序列结束时才出现——答案对错、格式是否合法、或者偏好模型打的一个标量。中间 token 没有逐步环境反馈。PPO 用 Critic 去自举「前缀还值多少」，在长思维链上要学的是一个与策略同样深的值函数，显存和滞后都会变成一等成本。</p><p>REINFORCE 的问题设定更窄：既然奖励是序列级的，就用蒙特卡洛回报当信用，把整段 \\(\\log\\pi_\\theta(y\\mid x)\\) 乘上同一个 \\((R-b)\\)。代价是方差大：同一道题，有的样本 \\(R=1\\)、有的 \\(R=0\\)，梯度噪声直接打进所有 token。要解决的不是「策略梯度能不能用」，而是「在没有 Critic 的前提下，如何让这条估计器在几百 token 的思维链上还能更新」。</p><h3 id="语言模型是回合制、奖励稀疏的策略" tabindex="-1">语言模型是回合制、奖励稀疏的策略 <a class="header-anchor" href="#语言模型是回合制、奖励稀疏的策略" aria-label="Permalink to &quot;语言模型是回合制、奖励稀疏的策略&quot;">​</a></h3><p>与游戏里每步有即时分不同，数学、代码、格式约束通常只在 EOS 处给一个数。折扣 \\(\\gamma=1\\)、中间 \\(r_t=0\\) 时，每一步的回报都等于终端 \\(R\\)。于是 token 级优势退化成同一个标量，广播到整段。这不是实现偷懒，而是稀疏奖励下蒙特卡洛估计的定义。谁先写对、谁在中途走错，REINFORCE 本身不分辨——那是<a href="/llm/prm-guided-search">过程奖励</a>或逐步验证要补的结构。</p><p><span class="marginnote">不要把 REINFORCE 写成「比 PPO 更旧所以更差」。PPO 的裁剪与 GAE 是为了稳定 <em>有 Critic</em> 的更新；当你已经决定不训 Critic、奖励又是可验证的 0/1，Williams 估计器才是与数据生成过程同构的那一条，PPO 的价值头反而可能是多余的偏置源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对提示 \\(x\\) 从 \\(\\pi_\\theta\\) 采样 \\(y\\)，得到标量回报 \\(R(x,y)\\)（规则、奖励模型或二者之和）。Williams 的无偏估计是</p> \\[\\nabla_\\theta J(\\theta) \\;\\approx\\; \\bigl(R(x,y)-b(x)\\bigr)\\, \\nabla_\\theta \\log\\pi_\\theta(y\\mid x), \\]<p>其中</p> \\[\\log\\pi_\\theta(y\\mid x)=\\sum_{t=1}^{|y|}\\log\\pi_\\theta(y_t\\mid x,y_{&lt;t}). \\]<p>\\(b(x)\\) 可以是 0、提示上的移动平均、贪心解码的回报（ReMax 一类），或同提示上其他样本的函数（<a href="/llm/group-relative-baseline">群体相对</a>、留一法）。只要 \\(b\\) 不依赖当前这条 \\(y\\) 里正在反传的那些 token，估计仍无偏，方差通常下降。</p><h3 id="r3-回报、梯度、正则三条绑在一起" tabindex="-1">R3：回报、梯度、正则三条绑在一起 <a class="header-anchor" href="#r3-回报、梯度、正则三条绑在一起" aria-label="Permalink to &quot;R3：回报、梯度、正则三条绑在一起&quot;">​</a></h3><p>工程路径很少只留纯 \\(\\mathbb{E}[R\\nabla\\log\\pi]\\)。常见三件套是：</p><ol><li><strong>Return</strong>：序列级 \\(R\\)，可验证任务上常是 0/1 再加格式分。</li><li><strong>REINFORCE</strong>：用 \\((R-b)\\) 缩放整段对数概率，或对每个 token 乘同一优势再按长度平均。</li><li><strong>Regularizer</strong>：对参考策略 \\(\\pi_{\\mathrm{ref}}\\) 加 KL，或在重要性比率上裁剪，防止更新把分布拉崩。</li></ol><p>本篇把这三件套叫 R3。它不是新的定理：KL 项来自 RLHF 实践（Ouyang 等 InstructGPT，2022），裁剪来自 Schulman 等的 PPO（2017），梯度本体仍是 Williams。实现上可以没有价值网络、没有 GAE \\(\\lambda\\)，但几乎总会留下参考模型或冻结的 SFT 锚。少了第三条，高奖励样本会把低频 token 的概率打到数值不稳定的区域；少了基线，批次里全对或全错时梯度要么爆炸要么为零。</p>',19)),(e(),E(p,null,{default:i(()=>[m(l,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20PI%5B%22%E7%AD%96%E7%95%A5%20%CF%80%CE%B8%20%E9%87%87%E6%A0%B7%20y%22%5D%0A%20%20PI%20--%3E%20R%5B%22%E5%BA%8F%E5%88%97%E5%9B%9E%E6%8A%A5%20R%22%5D%0A%20%20X%20--%3E%20B%5B%22%E5%9F%BA%E7%BA%BF%20b(x)%EF%BC%8C%E4%B8%8D%E4%BE%9D%E8%B5%96%E6%9C%AC%E6%9D%A1%20y%20%E7%9A%84%E5%8F%8D%E4%BC%A0%22%5D%0A%20%20R%20--%3E%20A%5B%22%E4%BC%98%E5%8A%BF%20R%20%E2%88%92%20b%22%5D%0A%20%20B%20--%3E%20A%0A%20%20PI%20--%3E%20LOG%5B%22%CE%A3%20log%20%CF%80%CE%B8(yt%20%7C%20%E5%89%8D%E7%BC%80)%22%5D%0A%20%20A%20--%3E%20G%5B%22REINFORCE%20%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20LOG%20--%3E%20G%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E7%AD%96%E7%95%A5%20%CF%80ref%22%5D%20--%3E%20KL%5B%22KL%20%E6%AD%A3%E5%88%99%22%5D%0A%20%20PI%20--%3E%20KL%0A%20%20G%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%20%CE%B8%22%5D%0A%20%20KL%20--%3E%20UPD%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无偏性来自策略梯度定理：在期望意义下，\\(\\mathbb{E}_{y\\sim\\pi}[(R-b)\\nabla\\log\\pi(y)]\\) 等于 \\(\\nabla\\mathbb{E}[R]\\)，只要 \\(b\\) 对当前动作可视为常数。方差来自 \\(R\\) 本身的波动，以及 \\(\\nabla\\log\\pi\\) 在长序列上的范数——思维链一长，对数概率是许多项的和，同等优势会被长度放大。所以实现必须先约定损失是「token 平均」还是「序列和」：前者让长短答案的有效步长更接近，后者会偏向更长的轨迹。R1 类训练里长度上升，部分正是因为更长的搜索提高了组内相对回报；这是目标在定价「思考时间」，不是优化器偷偷改了架构。</p><p>与 Actor-Critic 的差别在信用分配的分辨率。Critic 可以给每个前缀不同的 \\(V(s_t)\\)，使后半段的错误少牵连已经正确的前缀。REINFORCE 把同一标量打到每一个 token 上：对的前缀和错的后缀一起被加强或一起被抑制。<a href="/llm/group-relative-baseline">群体相对基线</a>只降低 <em>提示之间</em> 的尺度差异，不恢复 <em>序列内部</em> 的时间结构。若任务真的需要逐步对错，应把过程分写成显式奖励，而不是指望纯 REINFORCE 自己学会逐步信用。</p><p><span class="marginnote">对「停用 token」或填充位置必须把损失掩掉。否则 padding 的对数概率也会乘上优势，模型会学到用无意义长度去凑奖励。长度惩罚应写进 \\(R\\)，不要靠没掩码的 pad 当隐式正则。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="可验证奖励之外-纯蒙特卡洛会很吵" tabindex="-1">可验证奖励之外，纯蒙特卡洛会很吵 <a class="header-anchor" href="#可验证奖励之外-纯蒙特卡洛会很吵" aria-label="Permalink to &quot;可验证奖励之外，纯蒙特卡洛会很吵&quot;">​</a></h3><p>开放式写作、多目标偏好、奖励模型本身在漂移时，单条 \\(R\\) 的噪声大于 0/1 数学题。这时 PPO 的 Critic 或离线偏好方法可能更稳，不是因为 REINFORCE「过时」，而是因为基线估不准。组大小为 1 且 \\(b=0\\) 时，R3 退化成带 KL 的原始 REINFORCE，简单题会过拟合到少数提示，难题梯度稀疏。参考策略必须与采样策略同源：用过期的 SFT 当 \\(\\pi_{\\mathrm{ref}}\\) 而在线策略已经走远，KL 会变成恒定的拖曳，看起来像「不收敛」。</p><p>不要把温度、top-\\(p\\) 写进训练目标却在采样时关掉。REINFORCE 的期望是对 <em>实际采样分布</em> 取的；推理用贪心、训练用 \\(T=1.0\\)，优化的是另一个策略。评测若截断 <code>max_tokens</code>，终端奖励统计的是截断分布，梯度与产品行为脱节。R3 省的是 Critic 显存，不省采样：每步更新仍要若干完整 rollout，墙钟往往被 decode 带宽限制，见<a href="/llm/decode-memory-wall">Decode 的显存墙</a>。</p><p><span class="marginnote">引用停留在 Williams 1992 年的期刊论文、InstructGPT 的 KL 约束实践，以及 DeepSeekMath / R1 报告里对策略梯度族的采用。不要给「R3」编造 arXiv；它在本系列里是工程配方名，不是一篇独立论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REINFORCE 用蒙特卡洛回报乘 \\(\\nabla\\log\\pi\\)，不必学习值函数；基线只要不依赖当前动作，降方差且保持无偏。</li><li>语言模型把整段生成当一条轨迹，稀疏终端奖励使优势在 token 上广播为同一标量。</li><li>R3 指回报、REINFORCE 梯度、参考 KL/裁剪三件套，不是新的理论对象。</li><li>损失按 token 平均还是按序列求和，会改变长度激励；填充必须掩码。</li><li>组内基线与过程奖励解决的是不同问题：前者稳尺度，后者才有逐步信用。</li><li>采样分布必须与梯度假设一致；截断生成等于在评测另一条策略。</li><li>出处：Williams, <em>Simple Statistical Gradient-Following Algorithms for Connectionist Reinforcement Learning</em>, Machine Learning, 1992；Ouyang et al., <em>InstructGPT</em>, 2022；Shao et al., <em>DeepSeekMath</em>, 2024。</li></ul>',11))])}const u=r(R,[["render",h]]);export{g as __pageData,u as default};
